    ('S_SRC_RAW', 'LQ', 'SOURCE', 'RAW'),
    ('S_PT_RAW', 'LQ', 'PT_POST', 'RAW'),
    ('J_SRC_RAW', 'J3', 'SOURCE', 'RAW'),
    ('J_PT_RAW', 'J3', 'PT_POST', 'RAW'),
