def attr_json(path, obj):
    """元数据采用同目录临时文件加原子替换，磁盘满时不截断旧的进度文件。"""
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    temp = path.with_name(path.name + f'.tmp_{os.getpid()}')
    try:
        with temp.open('w', encoding='utf-8') as stream:
            json.dump(obj, stream, ensure_ascii=False, indent=2, allow_nan=False)
            stream.flush()
            os.fsync(stream.fileno())
        os.replace(temp, path)
    finally:
        if temp.exists():
            temp.unlink()


# 只替换本独立入口的元数据写入器，不修改封存作者文件。
save_json = attr_json


def attr_registry():
    """六个核心臂在每个seed内随机排列；边界核查不根据已观察结果选K或seed。"""
    rng = random.Random(20261031)
    tasks = []
    for seed in ATTR_SEEDS:
        arms = list(ATTR_ARMS)
        rng.shuffle(arms)
        for arm, control, reward_mode, time_mode in arms:
            tasks.append(dict(id=f'CORE__E1__K3__{arm}__s{seed}', stage='CORE',
                environment='E1', k=3, fleet=12, seed=seed, arm=arm, control=control,
                reward_mode=reward_mode, time_mode=time_mode, variant='M0_BASE',
                method=('J3' if control == 'J3' else 'SINGLE') + '__M0_BASE'))
    for k in (2, 4):
        arms = list(ATTR_ARMS[2:4])
        rng.shuffle(arms)
        for arm, control, reward_mode, time_mode in arms:
            tasks.append(dict(id=f'BOUNDARY__E1__K{k}__{arm}__s{ATTR_BOUNDARY_SEED}', stage='BOUNDARY',
                environment='E1', k=k, fleet=12, seed=ATTR_BOUNDARY_SEED, arm=arm, control=control,
                reward_mode=reward_mode, time_mode=time_mode, variant='M0_BASE', method='J3__M0_BASE'))
    for i, task in enumerate(tasks, 1):
        task['run_order'] = i
    assert len(tasks) == 28 and len({t['id'] for t in tasks}) == 28
    assert ATTR_PLANNED == 28_098_560 and ATTR_PLANNED < ATTR_CAP
    return tasks


def charging_pair(planes):
    """仅恢复本站现有飞机的两个充电时间统计槽；空闲飞机为0，不加入在途飞机。"""
    values = []
    for plane in planes:
        remaining = 0.
        if plane.state.name == 'CHARGING':
            rate = float(plane.spec.charge_rate_kwh_per_min)
            if not math.isfinite(rate) or rate <= 0:
                raise RuntimeError('充电率非正或非有限，不能制造虚假就绪时间')
            remaining = max(0., float(plane.spec.battery_capacity_kwh) - float(plane.battery_kwh)) / rate
        if not math.isfinite(remaining):
            raise RuntimeError('充电时间描述符非有限')
        values.append(remaining)
    return (sum(values) / len(values), min(values)) if values else (0., 0.)


def attr_unfinished(scenario):
    value = len(scenario.persons.persons) - len(set(scenario.finished_ids))
    if value < 0:
        raise AssertionError('完成集合与生成集合不自洽')
    return value


def policy_sha(policy):
    """只记录初始化参数，不读取或暴露凭据；同控制同seed各臂应逐位相同。"""
    h = hashlib.sha256()
    for name, tensor in sorted(policy.state_dict().items()):
        value = tensor.detach().cpu().contiguous()
        h.update(name.encode())
        h.update(str(value.dtype).encode())
        h.update(str(tuple(value.shape)).encode())
        h.update(value.numpy().tobytes())
    return h.hexdigest()


_attr_min_initialize = min_initialize
_attr_legacy_metrics = _base_episode_metrics
_attr_raw_resume_hook = full_resume_hook


def attr_initialize():
    global ATTR_INITIALIZED_PID, FullEnv, FullPPO
    if ATTR_INITIALIZED_PID == os.getpid():
        return
    _attr_min_initialize()
    OldEnv, OldPPO = FullEnv, FullPPO

    class AttributionEnv(OldEnv):
        def __init__(self, *args, **kwargs):
            self.reward_mode = os.environ.get('UAM_ATTR_REWARD', 'SOURCE')
            self.time_mode = os.environ.get('UAM_ATTR_TIME', 'RAW')
            self.air_override = os.environ.get('UAM_ATTR_AIR_OVERRIDE', 'POLICY')
            if self.reward_mode not in ('SOURCE', 'PT_POST') or self.time_mode not in ('RAW', 'CHARGE'):
                raise RuntimeError('归因开关未知，不使用隐式默认')
            if self.air_override != 'POLICY' and os.environ.get('UAM_ATTR_PHASE') != 'eval':
                raise RuntimeError('飞机规则替换只允许无训练评估，禁止混入训练')
            super().__init__(*args, **kwargs)
            if self.time_mode == 'CHARGE':
                original = self.raw.encoder.encode
                def encode(scenario, state):
                    frame = np.asarray(original(scenario, state), np.float32).copy()
                    stations = [str(v) for v in scenario.vertiports.vertiport_list if int(v) != 2]
                    if len(stations) != self.k or len(frame) != 4 + 8 * self.k:
                        raise AssertionError('源观测顺序或维数改变，拒绝猜测时间槽')
                    for i, vid in enumerate(stations):
                        average, fastest = charging_pair(scenario.vertiports.evtols_at_vertiport.get(vid, []))
                        frame[4 + 8*i + 5] = average
                        frame[4 + 8*i + 6] = fastest
                        self.attr_time_fields += 2
                        self.attr_positive_time_fields += int(average > 0) + int(fastest > 0)
                    return frame
                self.raw.encoder.encode = encode

        def reset(self, *args, **kwargs):
            self.attr_source_return = self.attr_applied_return = 0.
            self.attr_pre_area = self.attr_post_area = 0.
            self.attr_time_fields = self.attr_positive_time_fields = 0
            self.attr_trace = []
            result = super().reset(*args, **kwargs)
            self.attr_initial_unfinished = attr_unfinished(self.scenario)
            return result

        def prepare_step(self, actions):
            self.attr_tick_start = float(self.scenario.time)
            self.attr_before_unfinished = attr_unfinished(self.scenario)
            self.attr_passenger_active = bool(self.scenario.waiting_decisions)
            self.attr_passenger_action = int(actions[self.rank] if isinstance(actions, (list, tuple, np.ndarray)) else actions)
            return super().prepare_step(actions)

        def finish_step(self, actions):
            requested = int(actions[self.rank] if isinstance(actions, (list, tuple, np.ndarray)) else actions)
            actual = -1 if self.joint and self.air_override == 'LQ' else requested
            obs, source_reward, done, info = super().finish_step(actual)
            dt = float(self.scenario.time) - self.attr_tick_start
            if abs(dt - 1.) > 1e-9:
                raise AssertionError('源分钟时钟改变，不继续计账')
            unfinished = attr_unfinished(self.scenario)
            self.attr_pre_area += self.attr_before_unfinished * dt
            self.attr_post_area += unfinished * dt
            # 出生、到达等原事件在整数时刻发生后，对接下来一分钟计未完成人时。
            # 与历史分钟起点面积的差为终点未完成人数，完整完成时两者一致。
            if abs(self.attr_post_area-self.attr_pre_area-unfinished+self.attr_initial_unfinished) > 1e-7:
                raise AssertionError('人时双账望远镜恒等式不成立')
            applied = float(source_reward) if self.reward_mode == 'SOURCE' else -float(unfinished) * dt
            self.attr_source_return += float(source_reward)
            self.attr_applied_return += applied
            self._episode_reward += applied - float(source_reward)
            if self.log_details:
                self.attr_trace.append(dict(time=self.attr_tick_start, passenger_active=self.attr_passenger_active,
                    passenger=self.attr_passenger_action, aircraft_requested=requested, aircraft_applied=actual,
                    legal_aircraft=list(map(float, self._legal)), unfinished_before=self.attr_before_unfinished,
                    unfinished_after=unfinished, source_reward=float(source_reward), applied_reward=applied))
            if done:
                info['episode']['r'] = self._episode_reward
                info['attribution_ledger'] = self.attribution_ledger()
            return obs, applied, done, info

        def attribution_ledger(self):
            return dict(reward_mode=self.reward_mode, time_mode=self.time_mode, aircraft_override=self.air_override,
                source_return=self.attr_source_return, applied_return=self.attr_applied_return,
                person_time_pre=self.attr_pre_area, person_time_post=self.attr_post_area,
                initial_unfinished=self.attr_initial_unfinished, final_unfinished=attr_unfinished(self.scenario),
                charging_fields_encoded=self.attr_time_fields, positive_charging_fields=self.attr_positive_time_fields,
                scope='原始未归一化双账；gamma=.99，不称作未折扣全体ATT回报等价')

    class AttributionPPO(OldPPO):
        def __init__(self, *args, **kwargs):
            super().__init__(*args, **kwargs)
            if kwargs.get('_init_setup_model', True) and hasattr(self, 'policy'):
                if self.policy.features_extractor.auxiliary_parameters():
                    raise AssertionError('本轮不允许辅助头或额外网络优化')
                self.attr_initial_policy_sha = policy_sha(self.policy)
                folder = os.environ.get('UAM_ATTR_CELL')
                if folder:
                    save_json(Path(folder)/'INITIAL_POLICY_SHA.json', dict(sha256=self.attr_initial_policy_sha,
                        seed=self.seed, reward=os.environ['UAM_ATTR_REWARD'], time_mode=os.environ['UAM_ATTR_TIME']))

    for cls in (AttributionEnv, AttributionPPO):
        cls.__qualname__ = cls.__name__
        cls.__module__ = __name__
        globals()[cls.__name__] = cls
    FullEnv, FullPPO = AttributionEnv, AttributionPPO
    ATTR_INITIALIZED_PID = os.getpid()


initialize_full_runtime = attr_initialize


def terminal_snapshot(env):
    s = env.scenario
    candidates = tuple(str(v) for v in CANDIDATES[env.k])
    queues = {v:len(s.vertiports.vertiport_list[v].person_list) for v in candidates}
    ready = {v:sum(e.state.name=='IDLE' and not e.passenger_ids for e in s.vertiports.evtols_at_vertiport.get(v,[]))
             for v in candidates+('2',)}
    planes = list(s._all_evtols.values())
    stationary = len(planes)==12 and sum(ready.values())==12
    ended = s.time > s.passenger_generation_end_time
    blocked = (ended and stationary and ready['2']==0 and sum(queues.values())==attr_unfinished(s)
        and any(q>=4 and ready[v]==0 for v,q in queues.items())
        and all(queues[v]<4 for v in candidates if ready[v]>0))
    return dict(time=s.time, demand_generation_ended=ended, queues=queues, ready=ready,
        fleet=len(planes), restricted_executor_blocked=blocked,
        aircraft_states=dict(__import__('collections').Counter(e.state.name for e in planes)),
        label='RESTRICTED_EXECUTOR_BLOCKED' if blocked else 'COMPLETE' if attr_unfinished(s)==0 else 'OTHER_INCOMPLETE',
        scope='仅当前V2返回与满座动作集合；不是现实系统永远不能救援')


def attr_metrics(env, counts, area):
    result = _attr_legacy_metrics(env, counts, area)
    ledger = env.attribution_ledger()
    if abs(float(area)-ledger['person_time_pre']) > 1e-7:
        raise AssertionError('历史RPT与本轮分钟起点双账不同，拒绝混用指标')
    result.update(attribution_ledger=ledger, terminal_resource=terminal_snapshot(env),
        decision_trace=env.attr_trace, trace_sha256=os.environ.get('UAM_ATTR_TRACE_SHA'))
    return result


_base_episode_metrics = attr_metrics


def attr_setup(task, root, phase):
    os.environ.update(UAM_ATTR_REWARD=task.get('reward_mode','SOURCE'), UAM_ATTR_TIME=task.get('time_mode','RAW'),
        UAM_ATTR_AIR_OVERRIDE='POLICY', UAM_ATTR_PHASE=phase, UAM_ATTR_CELL=str(root/'cells'/task['id']),
        OMP_NUM_THREADS='1', MKL_NUM_THREADS='1', OPENBLAS_NUM_THREADS='1', NUMEXPR_NUM_THREADS='1')
    import torch
    torch.set_num_threads(1)
    if torch.get_num_interop_threads() != 1:
        torch.set_num_interop_threads(1)
    return full_setup(task, root)


def attr_update_manifest(folder, task):
    path = Path(folder)/'MODEL_MANIFEST.json'
    manifest = read_json(path, {})
    manifest.update(original_reward=task['reward_mode']=='SOURCE', reward_mode=task['reward_mode'],
        time_mode=task['time_mode'], attribution_arm=task['arm'], auxiliary='无辅助头、无额外优化器',
        architecture='封存M0源六帧LSTM128和原策略头，网络维度不变',
        reward_boundary='PT_POST按原整数事件完成后下一分钟；另存历史PRE账',
        main_claim_limit='gamma=.99；不是未折扣完整ATT等价；不把未完成者从服务质量中隐藏',
        entrypoint_sha256=digest(SCRIPT), anchor_git_blob=_ANCHOR_GIT_BLOB,
        scope='独立归因合同；不同于早期10env/gamma1的StageII')
    save_json(path, manifest)


def attr_train(task, root, config):
    global full_resume_hook
    directory = root/'cells'/task['id']
    pointer_file=directory/'RESUME_POINTER.json'
    pointer = read_json(directory/'RESUME_POINTER.json',{}) if config['resume'] else {}
    if config['resume'] and pointer_file.exists() and not pointer:
        raise RuntimeError('恢复指针损坏，不能悄悄从零覆盖同一cell')
    if config['resume'] and not pointer:
        attempts=[read_json(p,{}) for p in (directory/'attempts').glob('*.json')]
        if any(a.get('measured_transitions',0)>0 for a in attempts):
            raise RuntimeError('该格有已测训练工作但缺恢复指针，保留证据，不从零覆盖')
    start_step = int(pointer.get('step',0))
    measured, upper = budget_account(root)
    if measured+upper+max(0,ATTR_STEPS-start_step)>ATTR_CAP:
        raise RuntimeError('包含失败重做和未落盘尾段的预算上界将超过30M，不开始该格')
    attr_setup(task,root,'train')
    save_json(directory/'LIVE.json',dict(phase='train',steps=start_step,time=now(),pid=os.getpid()))
    attempt = directory/'attempts'/(str(time.time_ns())+'.json')
    save_json(attempt,dict(start_step=start_step,measured_transitions=0,unlogged_tail_upper_bound=20480,status='RUNNING',time=now()))
    original_hook = full_resume_hook
    def hook_factory(folder):
        previous = _attr_raw_resume_hook(folder)
        def hook(model):
            save_started=time.perf_counter()
            if shutil.disk_usage(root).free < 2*1024**3:
                raise RuntimeError('剩余磁盘不足2GiB，停止自己的worker，保留既有恢复件')
            previous(model)
            save_json(attempt,dict(start_step=start_step,last_logged_step=model.num_timesteps,
                measured_transitions=max(0,model.num_timesteps-start_step),unlogged_tail_upper_bound=20480,status='RUNNING',time=now()))
            rows=getattr(model,'_min_timing',[])
            attr_update_manifest(folder,task)
            if rows:
                rows[-1]['resume_save_seconds']=time.perf_counter()-save_started
                save_csv(Path(folder)/'TIMING.csv',rows)
        return hook
    full_resume_hook=hook_factory
    previous_segments=set((directory/'training').glob('segment_*'))
    try:
        _legacy_train(task,root,config)
        attr_update_manifest(directory,task)
    finally:
        full_resume_hook=original_hook
        maximum=max(start_step,int(read_json(attempt,{}).get('last_logged_step',start_step)))
        for segment in set((directory/'training').glob('segment_*'))-previous_segments:
            path=segment/'progress.csv'
            if path.is_file():
                with path.open(encoding='utf-8',errors='replace') as stream:
                    for row in csv.DictReader(stream):
                        if row.get('time/total_timesteps'):
                            maximum=max(maximum,int(float(row['time/total_timesteps'])))
        trained=read_json(directory/'TRAIN_END.json')
        if trained:
            maximum=max(maximum,int(trained['steps']))
        save_json(attempt,dict(start_step=start_step,last_logged_step=maximum,
            measured_transitions=max(0,maximum-start_step),unlogged_tail_upper_bound=20480,
            status='FINISHED' if trained else 'INTERRUPTED',time=now()))


def attr_eval(task,root,config):
    directory=attr_setup(task,root,'eval')
    import pickle
    started=time.perf_counter()
    points=[]
    for marker in sorted((directory/'checkpoints').glob('step_*.json')):
        cp=read_json(marker)
        step=int(cp['step'])
        destination=directory/'evaluation'/f'step_{step:09d}.json'
        existing=read_json(destination) if config['resume'] else None
        needs_intervention = step==ATTR_STEPS and task['control']=='J3' and not (directory/'FROZEN_AIRCRAFT_LQ.json').is_file()
        if existing and not needs_intervention:
            points.append(existing['summary'])
            continue
        model=FullPPO.load(marker.parent/Path(cp['model']).name,device=config['eval_device'])
        model.policy.set_training_mode(False)
        frozen_sha=policy_sha(model.policy)
        with (marker.parent/Path(cp['vecnorm']).name).open('rb') as stream:
            norm=pickle.load(stream)
        norm.training=False
        norm.norm_reward=False
        if norm.observation_space.shape!=(FullSchema(task['k']).dim,):
            raise RuntimeError('模型与归一化维数不配对')
        episodes=[]
        for seed in (123,124):
            result=full_replay(model,norm,root,task,dict(config,_capture_lifecycle=step==ATTR_STEPS,
                _final_checkpoint=step==ATTR_STEPS),seed,True,probe=False)
            result.update(trace_sha256=digest(config['trace']),reward_mode=task['reward_mode'],time_mode=task['time_mode'])
            episodes.append(result)
        summary=_full_summary_step(step,episodes)
        summary['DET_blocked_fraction']=mean([int(e['terminal_resource']['restricted_executor_blocked']) for e in episodes])
        summary['DET_co_available_episodes']=sum(e['ATT_completed_only'] is not None for e in episodes)
        save_json(destination,dict(task=task,step=step,summary=summary,episodes=episodes))
        save_json(directory/'LIVE.json',dict(phase='eval',checkpoint=step,
            elapsed_seconds=time.perf_counter()-started,time=now(),pid=os.getpid()))
        points.append(summary)
        if step==ATTR_STEPS and task['control']=='J3':
            # 不训练地替换飞机控制器，保持模型schema与joint标识；不是改物理或从终态救援。
            os.environ['UAM_ATTR_AIR_OVERRIDE']='LQ'
            try:
                ablated=[full_replay(model,norm,root,task,dict(config,_capture_lifecycle=True,_final_checkpoint=True),s,True,probe=False)
                         for s in (123,124)]
                save_json(directory/'FROZEN_AIRCRAFT_LQ.json',dict(task=task,episodes=ablated,
                    new_training_transitions=0,policy_sha256=frozen_sha,
                    scope='同一冻结模型的闭环飞机规则替换；乘客随后响应新状态，不是固定未来乘客动作序列'))
                save_json(directory/'LIVE.json',dict(phase='frozen_aircraft_lq_complete',checkpoint=step,
                    time=now(),pid=os.getpid()))
            finally:
                os.environ['UAM_ATTR_AIR_OVERRIDE']='POLICY'
        if policy_sha(model.policy)!=frozen_sha:
            raise AssertionError('冻结评估改变了策略权重')
        del model,norm
        print('[评估检查点]',task['id'],step,summary['DET_completion'],summary['DET_rpt'],flush=True)
    if not points or max(p['step'] for p in points)!=ATTR_STEPS:
        raise RuntimeError('最终检查点评估缺失，不报全格完成')
    if task['control']=='J3' and not (directory/'FROZEN_AIRCRAFT_LQ.json').is_file():
        raise RuntimeError('冻结飞机规则替换未完成，不把部分评估标为成功')
    points.sort(key=lambda p:p['step'])
    final=points[-1]
    late=[p for p in points if p['step']>=.8*ATTR_STEPS]
    available=[p for p in points if p['DET_co'] is not None]
    best=min(available,key=lambda p:p['DET_co']) if available else None
    result=dict(task=task,final=final,late=dict(co=mean([p['DET_co'] for p in late]),
        rpt=mean([p['DET_rpt'] for p in late]),completion=mean([p['DET_completion'] for p in late]),
        rpt_sd=sd([p['DET_rpt'] for p in late])),best_co_checkpoint=best,
        evaluation_scope='固定源训练CSV的两个随机回放，不是需求泛化；两次回放不算两个训练seed',
        checkpoint_selection='归因主比较固定最终checkpoint；Best只描述且并列完成率/RPT',eval_seconds=time.perf_counter()-started)
    save_json(directory/'RESULT.json',result)
    save_json(directory/'EVAL_END.json',dict(task=task,step=ATTR_STEPS,time=now()))


def attr_rules(task,root,config):
    attr_setup(task,root,'rules')
    _legacy_rules(task,root,config)


def attr_aggregate(root,tasks):
    status,rows=[],[]
    for task in tasks:
        folder=root/'cells'/task['id']
        train=read_json(folder/'TRAIN_END.json')
        result=read_json(folder/'RESULT.json')
        live=read_json(folder/'LIVE.json',{})
        unresolved=list(folder.glob('FAILED_*.json'))
        status.append(dict(**task,trained=bool(train),evaluated=bool(result),failed=bool(unresolved),
            steps=int(train['steps']) if train else int(live.get('steps',0))))
        if result:
            p=result['final']
            rows.append(dict(**task,step=p['step'],final_co=p['DET_co'],final_rpt=p['DET_rpt'],
                final_completion=p['DET_completion'],final_blocked=p['DET_blocked_fraction'],
                late_rpt=result['late']['rpt'],late_completion=result['late']['completion'],
                best_co=result['best_co_checkpoint']['DET_co'] if result['best_co_checkpoint'] else None,
                best_completion=result['best_co_checkpoint']['DET_completion'] if result['best_co_checkpoint'] else None,
                eval_seconds=result['eval_seconds']))
    pairs=[]
    by_key={(r['stage'],r['k'],r['seed'],r['arm']):r for r in rows}
    contrasts=(('REWARD_SINGLE','S_PT_RAW','S_SRC_RAW'),('REWARD_JOINT','J_PT_RAW','J_SRC_RAW'),
        ('CHARGE_SOURCE_JOINT','J_SRC_CHARGE','J_SRC_RAW'),('CHARGE_PT_JOINT','J_PT_CHARGE','J_PT_RAW'))
    for stage,k,seed in sorted({(r['stage'],r['k'],r['seed']) for r in rows}):
        for label,left,right in contrasts:
            a,b=by_key.get((stage,k,seed,left)),by_key.get((stage,k,seed,right))
            if a and b:
                pairs.append(dict(stage=stage,k=k,seed=seed,contrast=label,
                    delta_rpt=a['final_rpt']-b['final_rpt'],delta_completion=a['final_completion']-b['final_completion']))
        arm={name:by_key.get((stage,k,seed,name)) for name in [x[0] for x in ATTR_ARMS]}
        for label,names in (('REWARD_X_CONTROL',('J_PT_RAW','J_SRC_RAW','S_PT_RAW','S_SRC_RAW')),
                            ('REWARD_X_CHARGE_IN_J',('J_PT_CHARGE','J_PT_RAW','J_SRC_CHARGE','J_SRC_RAW'))):
            if all(arm[n] for n in names):
                a,b,c,d=[arm[n]['final_rpt'] for n in names]
                pairs.append(dict(stage=stage,k=k,seed=seed,contrast=label,delta_rpt=a-b-c+d,delta_completion=None))
    # 同控制、同seed初始化摘要核对不依赖实验结果；不将跨控制结构混为逐位等价。
    initial=defaultdict(set)
    for task in tasks:
        item=read_json(root/'cells'/task['id']/'INITIAL_POLICY_SHA.json')
        if item:
            initial[(task['stage'],task['k'],task['seed'],task['control'])].add(item['sha256'])
    if any(len(v)>1 for v in initial.values()):
        raise RuntimeError('同控制同seed初始策略权重不一致；不继续声称配对初始化')
    save_csv(root/'RUN_STATUS.csv',status)
    save_csv(root/'MODEL_RESULTS.csv',rows)
    save_csv(root/'PAIRED_EFFECTS.csv',pairs)
    measured,upper=budget_account(root)
    rules_done=sum((root/'cells'/f'RULES__E1__K{k}'/'RULES_END.json').is_file() for k in (2,3,4))
    failed_rules=sum(bool(list((root/'cells'/f'RULES__E1__K{k}').glob('FAILED_*.json'))) for k in (2,3,4))
    progress=dict(total=28,trained=sum(x['trained'] for x in status),evaluated=sum(x['evaluated'] for x in status),
        failed_cells=sum(x['failed'] for x in status),planned_actual_budget=ATTR_PLANNED,budget_cap=ATTR_CAP,
        rules_completed=rules_done,rules_total=3,failed_rules=failed_rules,
        completed_training_transitions=sum(x['steps'] for x in status if x['trained']),
        measured_training_work=measured,interrupted_unlogged_upper_bound=upper,time=now())
    save_json(root/'progress.json',progress)
    return progress


def attr_launch(phase,task,root,config):
    folder=root/'cells'/task['id']
    folder.mkdir(parents=True,exist_ok=True)
    marker=folder/('TRAIN_END.json' if phase=='train' else 'EVAL_END.json' if phase=='eval' else 'RULES_END.json')
    failure=folder/f'FAILED_{phase}.json'
    if marker.exists():
        if failure.exists() and config['retry_failed']:
            failure.rename(folder/f'RESOLVED_{phase}_{time.time_ns()}.json')
        return True
    if failure.exists() and not config['retry_failed']:
        print('[保留失败，继续后续格]',task['id'],phase,flush=True)
        return False
    task_file=folder/'TASK.json'
    save_json(task_file,dict(task=task,config=config))
    command=[sys.executable,'-B','-u',str(SCRIPT),'--worker',phase,'--task',str(task_file),'--root',str(root)]
    print('['+phase.upper()+']',task['id'],now(),flush=True)
    start=time.monotonic()
    with (folder/(phase+'.log')).open('a',encoding='utf-8') as stream:
        process=subprocess.Popen(command,stdout=stream,stderr=subprocess.STDOUT,stdin=subprocess.DEVNULL)
        try:
            while process.poll() is None:
                save_json(root/'RUNNING.json',dict(phase=phase,task=task,pid=process.pid,
                    elapsed_seconds=time.monotonic()-start,worker_progress=read_json(folder/'LIVE.json',{}),time=now()))
                if time.monotonic()-start>config['timeout_hours']*3600:
                    raise TimeoutError('当前隔离worker超过声明时限')
                time.sleep(5)
        except BaseException as error:
            # 只终止本父进程刚启动的隔离worker；不按名称批量杀进程。
            if process.poll() is None:
                process.terminate()
                try:
                    process.wait(timeout=30)
                except subprocess.TimeoutExpired:
                    process.kill()
                    process.wait()
            if not isinstance(error,TimeoutError):
                raise
    passed=process.returncode==0 and marker.is_file()
    if not passed:
        save_json(failure,dict(task=task,phase=phase,returncode=process.returncode,time=now(),
            note='原日志和恢复件保留；其余格继续；--resume --retry-failed重试'))
    elif failure.exists():
        failure.rename(folder/f'RESOLVED_{phase}_{time.time_ns()}.json')
    return passed


def attr_resource_check(root,device,min_free_gib):
    free=shutil.disk_usage(root).free/1024**3
    if free<min_free_gib:
        raise RuntimeError(f'磁盘只余{free:.2f}GiB，低于声明的{min_free_gib}GiB；不开始新格')
    if device.startswith('cuda'):
        visible=os.environ.get('CUDA_VISIBLE_DEVICES')
        if visible is None or not visible.strip() or ',' in visible:
            raise RuntimeError('共享服务器必须显式指定一张CUDA_VISIBLE_DEVICES，不自动占多卡')
        query=subprocess.run(['nvidia-smi','-i',visible,'--query-gpu=memory.free,utilization.gpu',
            '--format=csv,noheader,nounits'],capture_output=True,text=True,timeout=15)
        if query.returncode!=0:
            raise RuntimeError('无法核验选定GPU，未运行训练')
        fields=query.stdout.strip().split(',')
        if len(fields)!=2 or float(fields[0])<2048 or float(fields[1])>=95:
            raise RuntimeError('选定GPU显存不足2GiB或利用率达到95%，不开始新训练；请先查看资源')
    save_json(root/'RESOURCE_LAST_CHECK.json',dict(disk_free_gib=free,device=device,
        visible=os.environ.get('CUDA_VISIBLE_DEVICES'),time=now(),note='仍需用户按共享规范查看top；仅限制自己的线程与并行数'))


def attr_pack(root):
    archive=root.parent.parent/'experiment_archives'/(root.name+'_DATAONLY.tar.gz')
    archive.parent.mkdir(parents=True,exist_ok=True)
    expected_parent=archive.parent.resolve()
    if archive.is_symlink() or archive.resolve().parent!=expected_parent:
        raise RuntimeError('数据包路径重定向，拒绝改写')
    temporary=archive.with_suffix(archive.suffix+'.tmp')
    with tarfile.open(temporary,'w:gz') as arc:
        for path in sorted(root.rglob('*')):
            if path.is_file() and not path.is_symlink() and path.suffix.lower() in ('.json','.csv','.log','.py','.txt','.md','.html'):
                if '.tmp_' not in path.name and path.name!='DATA_PACKAGE.json':
                    arc.add(path,arcname=root.name+'/'+path.relative_to(root).as_posix(),recursive=False)
        arc.add(SCRIPT,arcname=root.name+'/ENTRYPOINT.py',recursive=False)
    if archive.exists():
        # 仅给当前私有实验的同名旧包留备份；不删除旧数据，下载文件名保持稳定。
        with tarfile.open(archive,'r:gz') as previous:
            member=previous.getmember(root.name+'/SUITE_PLAN.json')
            contract=json.load(previous.extractfile(member))
            if contract.get('script_sha256')!=digest(SCRIPT):
                raise RuntimeError('同名旧包不是本轮代码合同，不覆盖')
        backup=archive.with_name(root.name+'_'+str(time.time_ns())+'_PREVIOUS_DATAONLY.tar.gz')
        if backup.resolve().parent!=expected_parent or backup.exists():
            raise RuntimeError('备份目标不合法，不移动旧包')
        archive.rename(backup)
    os.replace(temporary,archive)
    save_json(root/'DATA_PACKAGE.json',dict(path=str(archive),sha256=digest(archive),time=now(),
        note='同名最新包；旧包若存在已留PREVIOUS备份'))
    print('[数据包，不含模型]',archive,flush=True)
    return str(archive)


def attr_main():
    parser=argparse.ArgumentParser(description='严格E1奖励/充电接口归因，28.099M实际步，30M硬上限')
    parser.add_argument('--root')
    parser.add_argument('--resume',action='store_true')
    parser.add_argument('--retry-failed',action='store_true')
    parser.add_argument('--phase',choices=('all','train','eval','rules','pack'),default='all')
    parser.add_argument('--device',default='cuda')
    parser.add_argument('--eval-device',default='cpu')
    parser.add_argument('--timeout-hours',type=float,default=3.)
    parser.add_argument('--min-free-gib',type=float,default=10.)
    parser.add_argument('--plan',action='store_true')
    parser.add_argument('--worker',choices=('train','eval','rules'))
    parser.add_argument('--task')
    args=parser.parse_args()
    if args.plan:
        print(json.dumps(dict(version=ATTR_VERSION,tasks=attr_registry(),actual_budget=ATTR_PLANNED,
            hard_cap=ATTR_CAP,reserved=ATTR_CAP-ATTR_PLANNED,anchor_git_blob=_ANCHOR_GIT_BLOB),ensure_ascii=False,indent=2))
        return
    project=Path(__file__).resolve().parent
    root=Path(args.root).resolve() if args.root else project/'serial_runs'/ATTR_ROOT
    if root.name!=ATTR_ROOT or not root.is_relative_to(project/'serial_runs') or root.is_symlink():
        raise RuntimeError('输出必须是本项目serial_runs下的新归因目录，不覆盖其他实验')
    if args.worker:
        record=read_json(args.task)
        if not record:
            raise RuntimeError('缺少任务合同')
        os.environ['UAM_ATTR_TRACE_SHA']=digest(record['config']['trace'])
        try:
            dict(train=attr_train,eval=attr_eval,rules=attr_rules)[args.worker](record['task'],root,record['config'])
        except BaseException:
            traceback.print_exc()
            raise
        return
    root.mkdir(parents=True,exist_ok=True)
    # 文件锁随父进程退出自动释放；不会因为服务器重启留下永久阻塞的PID锁。
    lock=(root/'PARENT_LOCK').open('a+b')
    if os.name=='nt':
        import msvcrt
        lock.seek(0)
        if lock.read(1)==b'':
            lock.write(b'0');lock.flush()
        lock.seek(0)
        msvcrt.locking(lock.fileno(),msvcrt.LK_NBLCK,1)
    else:
        import fcntl
        fcntl.flock(lock.fileno(),fcntl.LOCK_EX|fcntl.LOCK_NB)
    tasks=attr_registry()
    plan=root/'SUITE_PLAN.json'
    old=read_json(plan)
    if plan.exists() and not old:
        raise RuntimeError('已有实验合同损坏，不覆盖原计划')
    if not old and (root/'cells').exists() and any((root/'cells').iterdir()):
        raise RuntimeError('目录已有cell但缺实验合同，不覆盖其他或损坏的实验')
    if old and not args.resume and args.phase!='pack':
        raise RuntimeError('已有独立实验；恢复请加--resume，不清空或覆盖原目录')
    if old and old.get('script_sha256')!=digest(SCRIPT):
        raise RuntimeError('代码hash变化，不混入既有训练；请明确建立新版本合同')
    native=materialize_source(root)
    config=dict(version=ATTR_VERSION,device=args.device,eval_device=args.eval_device,
        trace=str(native/'train_data/passengers_300.csv'),train_horizon=500,eval_horizon=600,
        actual_steps=ATTR_STEPS,requested_steps=1_000_000,resume=args.resume,retry_failed=args.retry_failed,
        timeout_hours=args.timeout_hours)
    if old:
        for key in ('device','eval_device','trace','train_horizon','eval_horizon','actual_steps'):
            if old['config'][key]!=config[key]:
                raise RuntimeError('恢复合同改变：'+key)
    else:
        save_json(plan,dict(version=ATTR_VERSION,script_sha256=digest(SCRIPT),anchor_git_blob=_ANCHOR_GIT_BLOB,
            sealed_min_sha256=_SEALED_MIN_SHA256,source_commit=source_snapshot()['commit'],config=config,
            tasks=tasks,source_ppo=SOURCE_PPO,planned_actual_budget=ATTR_PLANNED,budget_cap=ATTR_CAP,
            description='两个共享对照的2×2设计；不估计Single的充电修复效果或三因素交互'))
    save_json(root/'TASK_REGISTRY.json',tasks)
    print('[预算] 28run×1,003,520='+str(ATTR_PLANNED)+'；上限30M；余量'+str(ATTR_CAP-ATTR_PLANNED),flush=True)
    try:
        if args.phase=='pack':
            attr_pack(root)
            return
        if args.phase in ('all','rules'):
            for k in (2,3,4):
                rule=dict(id=f'RULES__E1__K{k}',environment='E1',k=k,fleet=12,seed=123,control='LQ',
                    method='SINGLE__M0_BASE',variant='M0_BASE',arm='RULES',reward_mode='SOURCE',time_mode='RAW')
                attr_launch('rules',rule,root,config)
        for i,task in enumerate(tasks,1):
            if args.phase in ('all','train') and not (root/'cells'/task['id']/'TRAIN_END.json').exists():
                attr_resource_check(root,args.device,args.min_free_gib)
                print(f'[训练 {i}/28]',task['id'],flush=True)
                attr_launch('train',task,root,config)
            if args.phase in ('all','eval') and (root/'cells'/task['id']/'TRAIN_END.json').exists():
                attr_launch('eval',task,root,config)
            attr_aggregate(root,tasks)
        progress=attr_aggregate(root,tasks)
        save_json(root/'END.json',dict(status='COMPLETE' if progress['evaluated']==28 and not progress['failed_cells']
            and progress['rules_completed']==3 and not progress['failed_rules'] else 'PARTIAL',
            progress=progress,time=now(),note='未自动筛选新方法；K2/K4仅一个训练seed'))
        save_json(root/'RUNNING.json',dict(phase='complete' if read_json(root/'END.json')['status']=='COMPLETE' else 'idle_partial',
            task=None,pid=None,time=now()))
        attr_pack(root)
        print('[结束]',progress,flush=True)
    except KeyboardInterrupt:
        attr_aggregate(root,tasks)
        save_json(root/'INTERRUPTED.json',dict(time=now(),note='同代码--resume继续；不删除原格'))
        raise SystemExit(130)
    finally:
        end=read_json(root/'END.json',{})
        save_json(root/'RUNNING.json',dict(phase='complete' if end.get('status')=='COMPLETE' else 'idle',task=None,pid=None,
            time=now(),note='本父会话已退出，以progress.json和失败日志为准'))
        lock.close()


if __name__=='__main__':
    attr_main()
